     1→import { create } from 'zustand';
     2→
     3→export type AnnotationType = 'line' | 'arrow' | 'circle' | 'rectangle' | 'text';
     4→
     5→export interface Annotation {
     6→  id: string;
     7→  type: AnnotationType;
     8→  points: number[][]; // 2D points on screen or 3D points in world space
     9→  color: string;
    10→  thickness?: number;
    11→  text?: string;
    12→  createdAt: Date;
    13→}
    14→
    15→interface AnnotationState {
    16→  annotations: Annotation[];
    17→  selectedAnnotationId: string | null;
    18→  selectedTool: AnnotationType | null;
    19→  selectedColor: string;
    20→  thickness: number;
    21→
    22→  // Actions
    23→  addAnnotation: (annotation: Omit<Annotation, 'id' | 'createdAt'>) => void;
    24→  removeAnnotation: (id: string) => void;
    25→  clearAnnotations: () => void;
    26→  selectAnnotation: (annotationId: string | null) => void;
    27→  setSelectedTool: (tool: AnnotationType | null) => void;
    28→  setSelectedColor: (color: string) => void;
    29→  setThickness: (thickness: number) => void;
    30→  getAnnotation: (annotationId: string) => Annotation | undefined;
    31→  updateAnnotationPoints: (id: string, points: number[][]) => void;
    32→  updateAnnotationPoint: (id: string, pointIndex: number, newPoint: number[]) => void;
    33→}
    34→
    35→export const useAnnotationStore = create<AnnotationState>((set, get) => ({
    36→  annotations: [],
    37→  selectedAnnotationId: null,
    38→  selectedTool: null,
    39→  selectedColor: '#ffff00', // Yellow default
    40→  thickness: 2,
    41→  
    42→  addAnnotation: (annotation) => {
    43→    const newAnnotation: Annotation = {
    44→      ...annotation,
    45→      id: `annotation-${Date.now()}-${Math.random()}`,
    46→      createdAt: new Date(),
    47→    };
    48→    set((state) => ({
    49→      annotations: [...state.annotations, newAnnotation],
    50→    }));
    51→  },
    52→  
    53→  removeAnnotation: (id) => {
    54→    set((state) => ({
    55→      annotations: state.annotations.filter((a) => a.id !== id),
    56→      selectedAnnotationId: state.selectedAnnotationId === id ? null : state.selectedAnnotationId,
    57→    }));
    58→  },
    59→  
    60→  clearAnnotations: () => {
    61→    set({ annotations: [], selectedAnnotationId: null });
    62→  },
    63→
    64→  selectAnnotation: (annotationId) => {
    65→    set({ selectedAnnotationId: annotationId });
    66→  },
    67→
    68→  setSelectedTool: (tool) => {
    69→    set({ selectedTool: tool });
    70→  },
    71→  
    72→  setSelectedColor: (color) => {
    73→    set({ selectedColor: color });
    74→  },
    75→  
    76→  setThickness: (thickness) => {
    77→    set({ thickness });
    78→  },
    79→
    80→  getAnnotation: (annotationId) => {
    81→    return get().annotations.find((a) => a.id === annotationId);
    82→  },
    83→
    84→  updateAnnotationPoints: (id, points) => {
    85→    set((state) => ({
    86→      annotations: state.annotations.map((a) =>
    87→        a.id === id ? { ...a, points } : a
    88→      ),
    89→    }));
    90→  },
    91→
    92→  updateAnnotationPoint: (id, pointIndex, newPoint) => {
    93→    set((state) => ({
    94→      annotations: state.annotations.map((a) => {
    95→        if (a.id !== id) return a;
    96→        const updatedPoints = [...a.points];
    97→        updatedPoints[pointIndex] = newPoint;
    98→        return { ...a, points: updatedPoints };
    99→      }),
   100→    }));
   101→  },
   102→}));
   103→

