     1→import { useEffect, useState } from 'react';
     2→import { usePlaybookStore } from '../../store/playbookStore';
     3→import { usePlaybook } from '../../hooks/usePlaybook';
     4→
     5→export function PlaybookPanel() {
     6→  const { playbooks, isLoading, loadPlaybooks } = usePlaybookStore();
     7→  const { loadScenario } = usePlaybook();
     8→  const [isOpen, setIsOpen] = useState(false);
     9→  
    10→  useEffect(() => {
    11→    loadPlaybooks();
    12→  }, [loadPlaybooks]);
    13→  
    14→  const handleLoad = async (id: number) => {
    15→    try {
    16→      await loadScenario(id);
    17→      setIsOpen(false);
    18→    } catch (error) {
    19→      console.error('Error loading playbook:', error);
    20→      alert('Failed to load playbook. Please try again.');
    21→    }
    22→  };
    23→  
    24→  const handleDelete = async (id: number) => {
    25→    if (confirm('Are you sure you want to delete this playbook?')) {
    26→      try {
    27→        await usePlaybookStore.getState().deletePlaybook(id);
    28→      } catch (error) {
    29→        console.error('Error deleting playbook:', error);
    30→        alert('Failed to delete playbook. Please try again.');
    31→      }
    32→    }
    33→  };
    34→  
    35→  return (
    36→    <>
    37→      <button
    38→        onClick={() => setIsOpen(!isOpen)}
    39→        className="absolute top-4 right-4 z-10 px-4 py-2 bg-white/90 backdrop-blur-sm rounded-lg shadow-lg hover:bg-white transition"
    40→      >
    41→        {isOpen ? '← Close' : '📚 Playbooks'}
    42→      </button>
    43→      
    44→      {isOpen && (
    45→        <div className="absolute top-16 right-4 z-10 w-80 bg-white/95 backdrop-blur-sm rounded-lg shadow-xl p-4 max-h-[calc(100vh-120px)] overflow-y-auto">
    46→          <h2 className="text-xl font-bold mb-4">Saved Playbooks</h2>
    47→          
    48→          {isLoading ? (
    49→            <div className="text-center py-8">Loading...</div>
    50→          ) : playbooks.length === 0 ? (
    51→            <div className="text-center py-8 text-gray-500">No saved playbooks</div>
    52→          ) : (
    53→            <div className="space-y-2">
    54→              {playbooks.map((playbook) => (
    55→                <div
    56→                  key={playbook.id}
    57→                  className="border rounded p-3 hover:bg-gray-50 transition"
    58→                >
    59→                  <div className="flex justify-between items-start mb-2">
    60→                    <div className="flex-1">
    61→                      <h3 className="font-semibold">{playbook.name}</h3>
    62→                      {playbook.description && (
    63→                        <p className="text-sm text-gray-600 mt-1">{playbook.description}</p>
    64→                      )}
    65→                      <p className="text-xs text-gray-400 mt-1">
    66→                        {new Date(playbook.createdAt).toLocaleDateString()}
    67→                      </p>
    68→                    </div>
    69→                  </div>
    70→                  <div className="flex gap-2 mt-2">
    71→                    <button
    72→                      onClick={() => playbook.id && handleLoad(playbook.id)}
    73→                      className="flex-1 px-3 py-1.5 bg-blue-500 text-white text-sm rounded hover:bg-blue-600 transition"
    74→                    >
    75→                      Load
    76→                    </button>
    77→                    <button
    78→                      onClick={() => playbook.id && handleDelete(playbook.id)}
    79→                      className="px-3 py-1.5 bg-red-500 text-white text-sm rounded hover:bg-red-600 transition"
    80→                    >
    81→                      Delete
    82→                    </button>
    83→                  </div>
    84→                </div>
    85→              ))}
    86→            </div>
    87→          )}
