     1→/**
     2→ * Annotation Type Definitions
     3→ *
     4→ * Uses TypeScript discriminated unions for type-safe annotation handling.
     5→ * Each annotation type has a `type` field as the discriminator.
     6→ */
     7→
     8→// Position type for 3D coordinates
     9→export type Position3D = [number, number, number]; // [x, y, z]
    10→
    11→// Base annotation properties shared by all annotation types
    12→export interface BaseAnnotation {
    13→  id: string;
    14→  color: string;
    15→  thickness: number;
    16→  createdAt: Date;
    17→}
    18→
    19→/**
    20→ * Text Label Annotation
    21→ * Displays text at a specific 3D position on the field
    22→ */
    23→export interface TextAnnotation extends BaseAnnotation {
    24→  type: 'text';
    25→  position: Position3D; // Single position where text is anchored
    26→  text: string;
    27→  fontSize?: number; // Optional custom font size
    28→}
    29→
    30→/**
    31→ * Arrow Annotation
    32→ * Directional arrow between two points on the field
    33→ */
    34→export interface ArrowAnnotation extends BaseAnnotation {
    35→  type: 'arrow';
    36→  startPoint: Position3D;
    37→  endPoint: Position3D;
    38→}
    39→
    40→/**
    41→ * Zone shape types for highlighting areas
    42→ */
    43→export type ZoneShape = 'circle' | 'rectangle';
    44→
    45→/**
    46→ * Zone Annotation
    47→ * Semi-transparent shape for highlighting areas of the field
    48→ */
    49→export interface ZoneAnnotation extends BaseAnnotation {
    50→  type: 'zone';
    51→  shape: ZoneShape;
    52→  center: Position3D;
    53→  // For circle: [radius], For rectangle: [width, height]
    54→  size: [number] | [number, number];
    55→  opacity?: number; // Default 0.3
    56→}
    57→
    58→/**
    59→ * Drawing Annotation
    60→ * Free-hand path created by continuous mouse movement
    61→ */
    62→export interface DrawingAnnotation extends BaseAnnotation {
    63→  type: 'drawing';
    64→  points: Position3D[]; // Array of points forming the path
    65→}
    66→
    67→/**
    68→ * Union type of all annotation types
    69→ * Use this when you need to handle any annotation
    70→ */
    71→export type Annotation = TextAnnotation | ArrowAnnotation | ZoneAnnotation | DrawingAnnotation;
    72→
    73→/**
    74→ * Type for the annotation type discriminator
    75→ */
    76→export type AnnotationType = Annotation['type'];
    77→
    78→/**
    79→ * All possible annotation types as a const array
    80→ */
    81→export const ANNOTATION_TYPES = ['text', 'arrow', 'zone', 'drawing'] as const;
    82→
    83→/**
    84→ * Default values for annotation properties
    85→ */
    86→export const DEFAULT_ANNOTATION_VALUES = {
    87→  color: '#ffff00', // Yellow
    88→  thickness: 2,
    89→  fontSize: 14,
    90→  zoneOpacity: 0.3,
    91→} as const;
    92→
    93→// ============================================================================
    94→// Type Guards
    95→// ============================================================================
    96→
    97→/**
    98→ * Type guard to check if an annotation is a TextAnnotation
    99→ */
   100→export function isTextAnnotation(annotation: Annotation): annotation is TextAnnotation {
   101→  return annotation.type === 'text';
   102→}
   103→
   104→/**
   105→ * Type guard to check if an annotation is an ArrowAnnotation
   106→ */
   107→export function isArrowAnnotation(annotation: Annotation): annotation is ArrowAnnotation {
   108→  return annotation.type === 'arrow';
   109→}
   110→
   111→/**
   112→ * Type guard to check if an annotation is a ZoneAnnotation
   113→ */
   114→export function isZoneAnnotation(annotation: Annotation): annotation is ZoneAnnotation {
   115→  return annotation.type === 'zone';
   116→}
   117→
   118→/**
   119→ * Type guard to check if an annotation is a DrawingAnnotation
   120→ */
   121→export function isDrawingAnnotation(annotation: Annotation): annotation is DrawingAnnotation {
   122→  return annotation.type === 'drawing';
   123→}
   124→
   125→// ============================================================================
   126→// Factory Types (for creating new annotations)
   127→// ============================================================================
   128→
   129→/**
   130→ * Input type for creating a new text annotation (without generated fields)
   131→ */
   132→export type CreateTextAnnotation = Omit<TextAnnotation, 'id' | 'createdAt'>;
   133→
   134→/**
   135→ * Input type for creating a new arrow annotation (without generated fields)
   136→ */
   137→export type CreateArrowAnnotation = Omit<ArrowAnnotation, 'id' | 'createdAt'>;
   138→
   139→/**
   140→ * Input type for creating a new zone annotation (without generated fields)
   141→ */
   142→export type CreateZoneAnnotation = Omit<ZoneAnnotation, 'id' | 'createdAt'>;
   143→
   144→/**
   145→ * Input type for creating a new drawing annotation (without generated fields)
   146→ */
   147→export type CreateDrawingAnnotation = Omit<DrawingAnnotation, 'id' | 'createdAt'>;
   148→
   149→/**
   150→ * Union type for creating any annotation type
   151→ */
   152→export type CreateAnnotation =
   153→  | CreateTextAnnotation
   154→  | CreateArrowAnnotation
   155→  | CreateZoneAnnotation
   156→  | CreateDrawingAnnotation;
   157→
   158→// ============================================================================
   159→// Update Types (for partial updates)
   160→// ============================================================================
   161→
   162→/**
   163→ * Partial update type for text annotations
   164→ */
   165→export type UpdateTextAnnotation = Partial<Omit<TextAnnotation, 'id' | 'type' | 'createdAt'>>;
   166→
   167→/**
   168→ * Partial update type for arrow annotations
   169→ */
   170→export type UpdateArrowAnnotation = Partial<Omit<ArrowAnnotation, 'id' | 'type' | 'createdAt'>>;
   171→
   172→/**
   173→ * Partial update type for zone annotations
   174→ */
   175→export type UpdateZoneAnnotation = Partial<Omit<ZoneAnnotation, 'id' | 'type' | 'createdAt'>>;
   176→
   177→/**
   178→ * Partial update type for drawing annotations
   179→ */
   180→export type UpdateDrawingAnnotation = Partial<Omit<DrawingAnnotation, 'id' | 'type' | 'createdAt'>>;
   181→
   182→/**
   183→ * Union type for updating any annotation type
   184→ */
   185→export type UpdateAnnotation =
   186→  | UpdateTextAnnotation
   187→  | UpdateArrowAnnotation
   188→  | UpdateZoneAnnotation
   189→  | UpdateDrawingAnnotation;
   190→
   191→// ============================================================================
   192→// Serialization Types (for persistence)
   193→// ============================================================================
   194→
   195→/**
   196→ * Serialized annotation for JSON storage
   197→ * Converts Date to ISO string for persistence
   198→ */
   199→export interface SerializedAnnotation {
   200→  id: string;
   201→  type: AnnotationType;
   202→  color: string;
   203→  thickness: number;
   204→  createdAt: string; // ISO date string
   205→  // Type-specific fields
   206→  position?: Position3D;
   207→  text?: string;
   208→  fontSize?: number;
   209→  startPoint?: Position3D;
   210→  endPoint?: Position3D;
   211→  shape?: ZoneShape;
   212→  center?: Position3D;
   213→  size?: [number] | [number, number];
   214→  opacity?: number;
   215→  points?: Position3D[];
   216→}
   217→
   218→/**
   219→ * Serialize an annotation for JSON storage
   220→ */
   221→export function serializeAnnotation(annotation: Annotation): SerializedAnnotation {
   222→  return {
   223→    ...annotation,
   224→    createdAt: annotation.createdAt.toISOString(),
   225→  } as SerializedAnnotation;
   226→}
   227→
   228→/**
   229→ * Deserialize an annotation from JSON storage
   230→ */
   231→export function deserializeAnnotation(data: SerializedAnnotation): Annotation {
   232→  const base = {
   233→    id: data.id,
   234→    color: data.color,
   235→    thickness: data.thickness,
   236→    createdAt: new Date(data.createdAt),
   237→  };
   238→
   239→  switch (data.type) {
   240→    case 'text':
   241→      return {
   242→        ...base,
   243→        type: 'text',
   244→        position: data.position!,
   245→        text: data.text!,
   246→        fontSize: data.fontSize,
   247→      } as TextAnnotation;
   248→
   249→    case 'arrow':
   250→      return {
   251→        ...base,
   252→        type: 'arrow',
   253→        startPoint: data.startPoint!,
   254→        endPoint: data.endPoint!,
   255→      } as ArrowAnnotation;
   256→
   257→    case 'zone':
   258→      return {
   259→        ...base,
   260→        type: 'zone',
   261→        shape: data.shape!,
   262→        center: data.center!,
   263→        size: data.size!,
   264→        opacity: data.opacity,
   265→      } as ZoneAnnotation;
   266→
   267→    case 'drawing':
   268→      return {
   269→        ...base,
   270→        type: 'drawing',
   271→        points: data.points!,
   272→      } as DrawingAnnotation;
   273→
   274→    default:
   275→      throw new Error(`Unknown annotation type: ${(data as SerializedAnnotation).type}`);
   276→  }
   277→}
   278→
   279→/**
   280→ * Serialize an array of annotations
   281→ */
   282→export function serializeAnnotations(annotations: Annotation[]): SerializedAnnotation[] {
   283→  return annotations.map(serializeAnnotation);
   284→}
   285→
   286→/**
   287→ *Deserialize an array of annotations
   288→ */
   289→export function deserializeAnnotations(data: SerializedAnnotation[]): Annotation[] {
   290→  return data.map(deserializeAnnotation);
   291→}
