    15→    if (!selectedTool) return;
    16→    
    17→    const handlePointerDown = (event: PointerEvent) => {
    18→      if (event.button !== 0) return; // Only left mouse button
    19→      
    20→      const rect = gl.domElement.getBoundingClientRect();
    21→      const x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    22→      const y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    23→      
    24→      raycaster.setFromCamera({ x, y } as any, camera);
    25→      
    26→      // Intersect with ground plane
    27→      const planeNormal = new Vector3(0, 1, 0);
    28→      const planePoint = new Vector3(0, 0, 0);
    29→      const intersection = raycaster.ray.intersectPlane(
    30→        new Plane(planeNormal, -planeNormal.dot(planePoint)),
    31→        new Vector3()
    32→      );
