    34→      if (intersection) {
    35→        const [x, z] = snapToField(intersection.x, intersection.z);
    36→        const point = [x, 0, z];
    37→        startPointRef.current = intersection.clone();
    38→        currentPointsRef.current = [point];
    39→        isDrawingRef.current = true;
    40→      }
    41→    };
