    28→  if (!annotation.text || annotation.points.length < 1) {
    29→    return null;
    30→  }
    31→
    32→  const [x, y, z] = annotation.points[0];
    33→  const fontSize = 2; // Base font size for visibility on field
    34→  const textHeight = 0.5; // Height above field for visibility
    35→
    36→  // Handle dragging with global pointer events in useFrame
    37→  useFrame((state) => {
    38→    if (isDragging && isSelected) {
    39→      raycaster.setFromCamera(state.pointer, camera);
    40→      const planeNormal = new Vector3(0, 1, 0);
    41→      const planePoint = new Vector3(0, 0, 0);
    42→      const intersection = raycaster.ray.intersectPlane(
    43→        new Plane(planeNormal, -planeNormal.dot(planePoint)),
    44→        new Vector3()
    45→      );
